import type { NextFunction, Request, Response } from 'express';
import { notificationRepository } from '../repositories/notification.repository.js';
import { getAuthenticatedUser } from '../middleware/auth.middleware.js';
import { sendSuccess } from '../utils/apiResponse.js';
import { emitNotification } from '../lib/socket.js';

/**
 * NOTIFICATIONS CONTROLLER (Phase 6).
 * Any authenticated user can read/mark their own inbox — no scope leakage required,
 * because notifications are generated by the server for the intended recipient only.
 */
export const notificationController = {
  async list(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const actor = getAuthenticatedUser(req);
      const query = res.locals['validatedQuery'] as { unreadOnly?: boolean; page: number; pageSize: number };
      const result = await notificationRepository.listForUser(actor.id, {
        skip: (query.page - 1) * query.pageSize,
        take: query.pageSize,
        unreadOnly: query.unreadOnly,
      });
      sendSuccess(res, {
        notifications: result.notifications.map((n) => ({
          id: n.id,
          type: n.type,
          category: n.category,
          priority: n.priority,
          title: n.title,
          message: n.message,
          referenceType: n.referenceType,
          referenceId: n.referenceId,
          isRead: n.isRead,
          createdAt: n.createdAt.toISOString(),
        })),
        total: result.total,
        unreadCount: result.unreadCount,
        page: query.page,
        pageSize: query.pageSize,
      }, 'Notifications retrieved');
    } catch (error) {
      next(error);
    }
  },

  async unreadCount(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const actor = getAuthenticatedUser(req);
      const count = await notificationRepository.unreadCount(actor.id);
      sendSuccess(res, { unreadCount: count }, 'Unread count retrieved');
    } catch (error) {
      next(error);
    }
  },

  async markRead(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const actor = getAuthenticatedUser(req);
      const { id } = res.locals['validatedParams'] as { id: string };
      const ok = await notificationRepository.markRead(id, actor.id);
      if (!ok) {
        res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'Notification not found.' } });
        return;
      }
      sendSuccess(res, { updated: true }, 'Notification marked as read');
    } catch (error) {
      next(error);
    }
  },

  async markAllRead(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const actor = getAuthenticatedUser(req);
      const count = await notificationRepository.markAllRead(actor.id);
      sendSuccess(res, { updated: count }, 'All notifications marked as read');
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/v1/notifications/test
   * Dev/QA trigger — creates a TEST_NOTIFICATION for the authenticated user
   * and emits it in real time. Safe: only ever writes to the caller's own inbox.
   */
  async testCreate(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const actor = getAuthenticatedUser(req);
      const now = new Date();
      const row = await notificationRepository.createOne(actor.id, {
        type: 'TEST_NOTIFICATION',
        title: 'Test notification',
        message: `This is a real-time test notification emitted at ${now.toLocaleTimeString('en-GB', { timeZone: 'Asia/Kolkata' })} IST. It appears instantly in your bell badge and toast — no page refresh needed.`,
        referenceType: null,
        referenceId: null,
      });
      const payload = {
        id: row.id,
        type: row.type,
        category: row.category,
        priority: row.priority,
        title: row.title,
        message: row.message,
        referenceType: row.referenceType,
        referenceId: row.referenceId,
        isRead: row.isRead,
        createdAt: row.createdAt.toISOString(),
      };
      emitNotification(actor.id, payload);
      sendSuccess(res, { notification: payload }, 'Test notification sent', 201);
    } catch (error) {
      next(error);
    }
  },
};
